                LessonPage(id: "course_309_d_ou_vient_la_science_fiction_p1", title: "La lunette change la question", content: ""),
                LessonPage(id: "course_309_d_ou_vient_la_science_fiction_p2", title: "Frankenstein donne sa forme au genre", content: ""),
                LessonPage(id: "course_309_d_ou_vient_la_science_fiction_p3", title: "Un nom venu bien plus tard", content: ""),
                LessonPage(id: "course_309_d_ou_vient_la_science_fiction_p4", title: "Une façon de penser le changement", content: ""),
            ],
            quiz: [
        QuizQuestion(id: "course_309_d_ou_vient_la_science_fiction_q1", question: "Quel auteur du IIe siècle envoie déjà son narrateur sur la Lune ?", options: ["Lucien de Samosate", "Homère", "Ovide", "Plutarque"], correctIndex: 0, explanation: "Dans son Histoire véritable, Lucien de Samosate raconte un voyage satirique jusqu'à la Lune, près de deux mille ans avant les vols spatiaux."),
        QuizQuestion(id: "course_309_d_ou_vient_la_science_fiction_q2", question: "Qu'est-ce que le Somnium de Kepler ?", options: ["Un récit de voyage vers la Lune, publié après la mort de l'auteur", "Un traité sur les orbites des planètes", "Un manuel de fabrication des lunettes", "Un poème sur les comètes"], correctIndex: 0, explanation: "Publié en 1634, le Somnium imagine un voyage vers la Lune et décrit la Terre vue de l'espace."),
        QuizQuestion(id: "course_309_d_ou_vient_la_science_fiction_q3", type: .numericSlider, question: "En quelle année Mary Shelley publie-t-elle Frankenstein ?", explanation: "Frankenstein paraît en 1818, en pleine révolution industrielle.", correctValue: 1818, sliderMin: 1750, sliderMax: 1900, tolerance: 5, unit: ""),
        QuizQuestion(id: "course_309_d_ou_vient_la_science_fiction_q4", question: "Quelle est la question centrale de Frankenstein, selon le cours ?", options: ["Ce qui arrive quand un savant utilise ses connaissances pour créer la vie", "Comment voyager dans le temps", "Si d'autres planètes sont habitées", "Comment une machine peut apprendre à penser"], correctIndex: 0, explanation: "Victor Frankenstein franchit une frontière tenue pour contre-nature, et son succès scientifique tourne au désastre."),
        QuizQuestion(id: "course_309_d_ou_vient_la_science_fiction_q5", type: .trueFalse, question: "Vrai ou faux : Hugo Gernsback a inventé la science-fiction.", options: ["Vrai", "Faux"], correctIndex: 1, explanation: "Gernsback n'a pas créé le genre : il lui a donné un nom reconnu, des magazines et un public."),
