        Course(
            id: "course_310_qui_a_trace_les_frontieres_de_l_afrique",
            title: "Qui a tracé les frontières de l'Afrique ?",
            description: "Sur la carte, les frontières africaines semblent tirées à la règle. Elles sont pourtant nées de traités, de guerres locales et d'un choix des États indépendants, pas d'une seule réunion à Berlin.",
            subject: .histoire,
            subcategory: "Époque moderne & XIXe siècle",
            lessons: [
                LessonPage(id: "course_310_qui_a_trace_les_frontieres_de_l_afrique_intro", title: "Introduction", content: ""),
                LessonPage(id: "course_310_qui_a_trace_les_frontieres_de_l_afrique_p1", title: "Revendiquer n'est pas gouverner", content: ""),
                LessonPage(id: "course_310_qui_a_trace_les_frontieres_de_l_afrique_p2", title: "Des frontières nées de conflits locaux", content: ""),
                LessonPage(id: "course_310_qui_a_trace_les_frontieres_de_l_afrique_p3", title: "Les nouveaux États héritent des cartes", content: ""),
                LessonPage(id: "course_310_qui_a_trace_les_frontieres_de_l_afrique_p4", title: "Des frontières aux nombreux auteurs", content: ""),
            ],
            quiz: [
        QuizQuestion(id: "course_310_qui_a_trace_les_frontieres_de_l_afrique_q1", question: "Qu'est-ce que la conférence de Berlin de 1884-1885 a réellement décidé ?", options: ["Les règles que les puissances européennes devaient suivre pour acquérir des colonies", "Le tracé définitif de toutes les frontières africaines", "L'indépendance des premiers États africains", "Le partage de l'Afrique entre deux puissances seulement"], correctIndex: 0, explanation: "La conférence fixe des règles du jeu entre Européens ; la plupart des frontières sont tracées ensuite, par traités, échanges de territoires et guerres."),
        QuizQuestion(id: "course_310_qui_a_trace_les_frontieres_de_l_afrique_q2", type: .trueFalse, question: "Vrai ou faux : les souverains africains ont participé à la conférence de Berlin sur un pied d'égalité avec les Européens.", options: ["Vrai", "Faux"], correctIndex: 1, explanation: "Les discussions se tiennent entre Européens ; les États et souverains africains n'y sont pas admis sur un pied d'égalité."),
        QuizQuestion(id: "course_310_qui_a_trace_les_frontieres_de_l_afrique_q3", question: "Que signifie le principe d'« occupation effective » adopté à Berlin ?", options: ["Un État doit prouver qu'il exerce réellement le pouvoir sur le territoire qu'il revendique", "Une colonie doit être peuplée de colons européens", "Un territoire appartient au premier explorateur qui l'a traversé", "Une frontière doit suivre un fleuve ou une montagne"], correctIndex: 0, explanation: "Colorier une carte ne suffit pas : il faut une armée, des fonctionnaires et un pouvoir réel sur place pour que la revendication soit reconnue."),
        QuizQuestion(id: "course_310_qui_a_trace_les_frontieres_de_l_afrique_q4", question: "Quel royaume d'Afrique de l'Ouest a longtemps résisté à la conquête britannique ?", options: ["Le royaume ashanti", "Le royaume du Kongo", "L'Empire éthiopien", "Le royaume zoulou"], correctIndex: 0, explanation: "Les Ashanti repoussent longtemps les Britanniques, qui finissent par intégrer leur territoire au système colonial."),
        QuizQuestion(id: "course_310_qui_a_trace_les_frontieres_de_l_afrique_q5", type: .trueFalse, question: "Vrai ou faux : toutes les frontières coloniales ont été tracées au hasard.", options: ["Vrai", "Faux"], correctIndex: 1, explanation: "Certaines suivent un fleuve, un lac, une montagne ou une limite politique plus ancienne, et les États précoloniaux ont pesé sur le tracé."),
        QuizQuestion(id: "course_310_qui_a_trace_les_frontieres_de_l_afrique_q6", question: "Que prévoit le principe de l'uti possidetis ?", options: ["Un nouvel État conserve le territoire qu'il possédait au moment de son indépendance", "Les frontières doivent être renégociées après chaque indépendance", "Chaque communauté a le droit de former son propre État", "Les anciennes puissances coloniales gardent un droit de regard sur les frontières"], correctIndex: 0, explanation: "Les dirigeants africains acceptent ce principe latin pour éviter que la remise en cause de chaque tracé ne mène à des guerres sans fin."),
        QuizQuestion(id: "course_310_qui_a_trace_les_frontieres_de_l_afrique_q7", type: .numericSlider, question: "En quelle année l'Organisation de l'unité africaine est-elle fondée ?", explanation: "L'OUA est fondée à Addis-Abeba en 1963 ; un an plus tard, ses dirigeants s'engagent à respecter les frontières héritées.", correctValue: 1963, sliderMin: 1945, sliderMax: 1990, tolerance: 2, unit: ""),
        QuizQuestion(id: "course_310_qui_a_trace_les_frontieres_de_l_afrique_q8", type: .chronological, question: "Remets ces événements dans l'ordre.", explanation: "1874, 1884-1885, 1963, puis 1964 : la conquête précède la conférence, et les indépendances confirment les tracés.", items: ["Les troupes britanniques marchent sur Kumasi, capitale ashanti", "La conférence de Berlin fixe les règles du partage colonial", "L'Organisation de l'unité africaine est fondée à Addis-Abeba", "Les dirigeants africains s'engagent à respecter les frontières héritées"])
    ]
